export function getTankItemIcon(slugOrId: string, customUrl?: string | null): string {
  const normalized = slugOrId.toLowerCase().replace(/_/g, "-");
  if (TANK_ITEM_ICONS[normalized]) return TANK_ITEM_ICONS[normalized];

  const aliases: Record<string, string> = {
    "deed-to-tank": "deed-to-tank",
    "deed-tank": "deed-to-tank",
    "starter-noisemaker": "didgeridoo",
    "letter": "love-letter",
    "heartfelt-letter": "love-letter",
    "simple-love-letter": "love-letter",
    "toy-sword": "lightsaber",
    "sword": "lightsaber",
    "batteries": "battery",
    "gloves": "boxing-gloves",
    "monitor": "broken-monitor",
  };

  const aliased = aliases[normalized];
  if (aliased && TANK_ITEM_ICONS[aliased]) {
    return TANK_ITEM_ICONS[aliased];
  }

  return customUrl || TANK_ITEM_ICONS["launch-keys"];
}

export function getTankItemEmoji(slugOrId: string): string {
  const normalized = slugOrId.toLowerCase().replace(/_/g, "-");
  return TANK_ITEM_CATALOG[normalized]?.emoji || "📦";
}
